-- Gold Roundtables — session domain (offline-first, synced by PowerSync; ADR 0003/0004/0005).
--
-- Sessions are generated by the server from each table's schedule (one pending session per
-- table), so every device has the session id before the meeting and can capture offline.
-- Child rows denormalize organization_id and round_table_id (set by trigger from the session)
-- so PowerSync sync rules can bucket them without joins; a composite foreign key keeps them
-- consistent with the parent session.
--
-- Sync metadata on every session-domain row (ADR 0005):
--   device_created_at / device_modified_at : device clock when the row was captured / edited
--   received_at                             : server clock when the upload was applied
--   synced_late                             : set by the server when the upload arrived after the
--                                             facilitator closed the session
--   archived_at                             : set when the row leaves the device sync window

create table public.sessions (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null references public.organizations (id),
  round_table_id uuid not null,
  -- The value worked in this session (initial score, reflection answers, commitment).
  value_id uuid not null references public.curriculum_values (id),
  -- The value worked in the previous closed session (follow-up score + commitment review).
  -- NULL for a table's first session.
  follow_up_value_id uuid references public.curriculum_values (id),
  status public.session_status not null default 'scheduled',
  stage public.session_stage not null default 'lobby',
  scheduled_at timestamptz not null,
  started_at timestamptz,
  ended_at timestamptz,
  answers_closed_at timestamptz,
  cancelled_reason text,
  -- Facilitator who ran the session (set when opened); KPIs group by it.
  facilitator_person_id uuid references public.people (id),
  device_modified_at timestamptz,
  archived_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (id, organization_id),
  unique (id, round_table_id, organization_id),
  constraint sessions_table_org_fkey foreign key (round_table_id, organization_id)
    references public.round_tables (id, organization_id),
  constraint sessions_stage_status_check check ((stage = 'closed') = (status = 'closed')),
  constraint sessions_scheduled_check check (
    status <> 'scheduled' or (stage = 'lobby' and started_at is null and ended_at is null)),
  constraint sessions_closed_check check (
    status <> 'closed' or (started_at is not null and ended_at is not null)),
  constraint sessions_dates_check check (ended_at is null or ended_at >= started_at),
  constraint sessions_follow_up_distinct_check check (follow_up_value_id is distinct from value_id)
);
-- One session per table per slot (ADR 0002) and at most one pending session per table.
create unique index sessions_table_slot_key on public.sessions (round_table_id, scheduled_at);
create unique index sessions_one_pending_key on public.sessions (round_table_id)
  where status in ('scheduled', 'open');
create index sessions_table_status_idx on public.sessions (round_table_id, status, ended_at desc);

create table public.session_attendance (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null,
  round_table_id uuid not null,
  session_id uuid not null,
  person_id uuid not null,
  status public.attendance_status not null,
  source public.attendance_source not null default 'facilitator',
  recorded_by_person_id uuid references public.people (id),
  device_created_at timestamptz not null default now(),
  device_modified_at timestamptz,
  received_at timestamptz not null default now(),
  synced_late boolean not null default false,
  archived_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (session_id, person_id),
  constraint session_attendance_session_fkey foreign key (session_id, round_table_id, organization_id)
    references public.sessions (id, round_table_id, organization_id),
  constraint session_attendance_person_org_fkey foreign key (person_id, organization_id)
    references public.people (id, organization_id)
);
create index session_attendance_table_idx on public.session_attendance (round_table_id);
create index session_attendance_person_idx on public.session_attendance (person_id);

create table public.member_assessments (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null,
  round_table_id uuid not null,
  session_id uuid not null,
  person_id uuid not null,
  value_id uuid not null references public.curriculum_values (id),
  kind public.assessment_kind not null,
  -- Integer 1–10; 5 is not allowed (PC-08, ADR 0005).
  score smallint not null constraint member_assessments_score_check
    check (score between 1 and 10 and score <> 5),
  justification text check (justification is null or length(justification) <= 2000),
  device_created_at timestamptz not null default now(),
  device_modified_at timestamptz,
  received_at timestamptz not null default now(),
  synced_late boolean not null default false,
  archived_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  -- One initial score per session (current value) and one follow-up score per session
  -- (previous value). Because follow_up_value_id is always the previous session's value, the
  -- follow-up happens exactly once, in the next session (PC-09).
  constraint member_assessments_session_person_kind_key unique (session_id, person_id, kind),
  constraint member_assessments_session_fkey foreign key (session_id, round_table_id, organization_id)
    references public.sessions (id, round_table_id, organization_id),
  constraint member_assessments_person_org_fkey foreign key (person_id, organization_id)
    references public.people (id, organization_id)
);
create index member_assessments_table_idx on public.member_assessments (round_table_id);
create index member_assessments_person_value_idx on public.member_assessments (person_id, value_id);

create table public.member_answers (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null,
  round_table_id uuid not null,
  session_id uuid not null,
  person_id uuid not null,
  value_id uuid not null references public.curriculum_values (id),
  question_id uuid not null references public.value_questions (id),
  answer_text text not null check (length(answer_text) <= 2000),
  device_created_at timestamptz not null default now(),
  device_modified_at timestamptz,
  received_at timestamptz not null default now(),
  synced_late boolean not null default false,
  archived_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint member_answers_session_person_question_key unique (session_id, person_id, question_id),
  constraint member_answers_session_fkey foreign key (session_id, round_table_id, organization_id)
    references public.sessions (id, round_table_id, organization_id),
  constraint member_answers_person_org_fkey foreign key (person_id, organization_id)
    references public.people (id, organization_id)
);
create index member_answers_table_idx on public.member_answers (round_table_id);
create index member_answers_person_idx on public.member_answers (person_id);

create table public.member_commitments (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null,
  round_table_id uuid not null,
  session_id uuid not null,
  person_id uuid not null,
  value_id uuid not null references public.curriculum_values (id),
  -- One concrete, measurable action for the coming week.
  action_text text not null check (length(btrim(action_text)) between 1 and 500),
  measure_text text check (measure_text is null or length(measure_text) <= 500),
  -- Follow-up, reported by the same person in the next session of the table.
  follow_up_session_id uuid references public.sessions (id),
  follow_up_status public.commitment_follow_up_status,
  follow_up_note text check (follow_up_note is null or length(follow_up_note) <= 2000),
  follow_up_device_at timestamptz,
  follow_up_received_at timestamptz,
  follow_up_synced_late boolean not null default false,
  device_created_at timestamptz not null default now(),
  device_modified_at timestamptz,
  received_at timestamptz not null default now(),
  synced_late boolean not null default false,
  archived_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint member_commitments_session_person_key unique (session_id, person_id),
  constraint member_commitments_session_fkey foreign key (session_id, round_table_id, organization_id)
    references public.sessions (id, round_table_id, organization_id),
  constraint member_commitments_person_org_fkey foreign key (person_id, organization_id)
    references public.people (id, organization_id),
  constraint member_commitments_follow_up_check check (
    follow_up_status is null or follow_up_session_id is not null),
  constraint member_commitments_follow_up_other_session_check check (
    follow_up_session_id is distinct from session_id)
);
create index member_commitments_table_idx on public.member_commitments (round_table_id);
create index member_commitments_person_idx on public.member_commitments (person_id);
create index member_commitments_follow_up_idx on public.member_commitments (follow_up_session_id);

create trigger sessions_touch before update on public.sessions
  for each row execute function app.touch_updated_at();
create trigger session_attendance_touch before update on public.session_attendance
  for each row execute function app.touch_updated_at();
create trigger member_assessments_touch before update on public.member_assessments
  for each row execute function app.touch_updated_at();
create trigger member_answers_touch before update on public.member_answers
  for each row execute function app.touch_updated_at();
create trigger member_commitments_touch before update on public.member_commitments
  for each row execute function app.touch_updated_at();
